window.AUTH=window.AUTH||{};window.AUTH["23-1275"]={"d":"23-1275","id":"2024/23-1275","n":"Medina v. Planned Parenthood South Atlantic","briefs":[{"k":"petitioner","label":"Brief of petitioner Eunice Medina, Interim Director, South Carolina Department of Health and Human Services","date":"2025-02-03","url":"https://www.supremecourt.gov/DocketPDF/23/23-1275/341725/20250203121003568_23-1275%20Brief%20for%20the%20Petitioner.pdf","side":"pet","n":63},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2025-02-10","url":"https://www.supremecourt.gov/DocketPDF/23/23-1275/342428/20250210202034617_23-1275tsacUnitedStates.pdf","side":"us","n":85},{"k":"respondent","label":"Brief of respondents Planned Parenthood South Atlantic, et al.","date":"2025-03-05","url":"https://www.supremecourt.gov/DocketPDF/23/23-1275/351315/20250305145751791_23-1275%20bs%20-%20Response%20Brief.pdf","side":"res","n":94},{"k":"reply","label":"Reply of petitioner Eunice Medina, Director, South Carolina Department of Health and Human Services","date":"2025-03-24","url":"https://www.supremecourt.gov/DocketPDF/23/23-1275/352784/20250324104442253_23-1275%20Reply%20Brief.pdf","side":"pet","n":36}],"opinion":"https://www.supremecourt.gov/opinions/24pdf/606us1r60_h3ci.pdf","tr":true,"items":[{"t":"case","label":"31 Foster Children v. Bush","cite":"329 F.3d 1255","y":2003,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/329/1255/","by":{"0":"22","3":"9"}},{"t":"case","label":"Alexander v. Sandoval","cite":"532 U.S. 275","y":2001,"id":"2000/99-1908","sc":1,"op":4,"sum":"The Court held that there is no private right of action to enforce disparate-impact regulations promulgated under Title VI. \"Title VI itself directly reaches only instances of intentional discrimination,\" wrote Justice Scalia, \"[n]either as originally enacted nor as later amended does Title VI display an intent to create a freestanding private right of action to enforce regulations promulgated under [section 602].\" Justice John Paul Stevens filed a dissenting opinion, which was join by Justices David H. Souter, Ruth Bader Ginsburg, and Stephen G. Breyer.","sumSrc":"Oyez","by":{"0":"19, 26, 28, 32, 37","1":"17","3":"22"}},{"t":"case","label":"Arizona v. Navajo Nation","cite":"599 U.S. 555","y":2023,"id":"2022/21-1484","sc":1,"op":30,"sum":"The 1868 treaty establishing the Navajo Reservation reserved necessary water to accomplish the purpose of the Navajo Reservation but did not require the United States to take affirmative steps to secure water for the Tribe.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"52–53"}},{"t":"case","label":"Armstrong v. Exceptional Child Center, Inc.","cite":"575 U.S. 320","y":2015,"id":"2014/14-15","sc":1,"op":7,"ar":4,"sum":"A case that determines whether or not a private right of action exists under the Medicaid Act.","sumSrc":"Oyez","by":{"0":"4, 35–36, 41, 46, 50","1":"5, 19, 21, 26","2":"4, 26, 33","3":"3, 10, 15, 17–19, 21–22"}},{"t":"case","label":"Baker v. Planned Parenthood South Atlantic","cite":"141 S. Ct. 550","y":2020,"url":"https://www.courtlistener.com/c/S.%20Ct./141/550/","sc":1,"by":{"0":"13","2":"10"}},{"t":"case","label":"Blessing v. Freestone","cite":"520 U.S. 329","y":1997,"id":"1996/95-1441","sc":1,"op":9,"ar":11,"sum":"The Court ruled that Title IV-D of the Social Security Act does not give individuals a federal right to force a state agency to substantially comply with Title IV-D. Justice O'Connor wrote for the court that parents cannot sue merely because a state fails to be in \"substantial compliance\" with federal collection standards.","sumSrc":"Oyez","by":{"0":"12, 45, 49, 51","1":"9, 18, 19","2":"17, 26"}},{"t":"case","label":"Bontrager v. Indiana Family & Social Services Administration","cite":"697 F.3d 604","y":2012,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/697/604/","by":{"0":"44"}},{"t":"case","label":"BT Bourbonnais Care, LLC v. Norwood","cite":"866 F.3d 815","y":2017,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/866/815/","by":{"0":"44"}},{"t":"case","label":"California v. Sierra Club","cite":"451 U.S. 287","y":1981,"id":"1980/79-1252","sc":1,"op":4,"sum":"Section 10 of the Rivers and Harbors AppropriationAct of 1899 (Act) prohibits \"[t]he creation of any obstruction not affirmatively authorized by Congress, to the navigable capacity of any of the waters of the United States.\" An environmental organization and two private citizens (hereafter respondents) brought an action in Federal District Court seeking to enjoin, as a violation of § 10, the construction and …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20"}},{"t":"case","label":"Cannon v. University of Chicago","cite":"441 U.S. 677","y":1979,"id":"1978/77-926","sc":1,"op":6,"sum":"Petitioner may maintain her lawsuit, despite the absence of any express authorization for it in Title IX.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19, 30–32"}},{"t":"case","label":"Carson ex rel. O. C. v. Makin","cite":"596 U.S. 767","y":2022,"id":"2021/20-1088","sc":1,"sum":"Maine’s “nonsectarian” requirement for otherwise generally available tuition assistance payments to parents who live in school districts that do not operate a secondary school of their own violates the Free Exercise Clause of the First Amendment.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"50"}},{"t":"case","label":"Correctional Services Corp. v. Malesko","cite":"534 U.S. 61","y":2001,"id":"2001/00-860","sc":1,"sum":"The Court held that Bivens' limited holding may not be extended to confer a right of action for damages against private entities acting under color of federal law. The Court reasoned that the threat of suit against an individual's employer was not the kind of deterrence contemplated by the Bivens decision.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"Doe v. Kidd","cite":"501 F.3d 348","y":2007,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/501/348/","by":{"0":"44"}},{"t":"case","label":"Does v. Gillespie","cite":"867 F.3d 1034","y":2017,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/867/1034/","op":1,"ar":1,"by":{"0":"13, 34, 42","1":"24, 26, 31","2":"24","3":"16, 18"}},{"t":"case","label":"Douglas v. Independent Living Center of Southern California, Inc.","cite":"565 U.S. 606","y":2012,"id":"2011/09-958","sc":1,"op":1,"sum":"A case which the Court remanded to the Ninth Circuit regarding whether or not federal law preempts state reductions in Medicaid payments.","sumSrc":"Oyez","by":{"0":"4"}},{"t":"case","label":"Federal Law Enforcement Officers Association v. Attorney General New Jersey","cite":"93 F.4th 122","y":2024,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.4th/93/122/","op":1,"sum":"Observing that this Court “has not expressly held that the Blessing factors are no longer relevant” and applying those factors in a footnote.","sumSrc":"brief:0","by":{"0":"48"}},{"t":"case","label":"Gee v. Planned Parenthood of Gulf Coast, Inc.","cite":"586 U.S. 1057","y":2018,"url":"https://supreme.justia.com/cases/federal/us/586/1057/","sc":1,"by":{"0":"53","1":"31","3":"2"}},{"t":"case","label":"Gonzaga University v. Doe","cite":"536 U.S. 273","y":2002,"id":"2001/01-679","sc":1,"op":37,"ar":35,"sum":"The Court held that such an action is foreclosed because the relevant provisions of FERPA create no personal rights to enforce.","sumSrc":"Oyez","by":{"0":"2, 16–20, 22–23, 25–26, 28–30, 34, 37,45–46, 49–51","1":"12, 15-19, 21-24, 30, 31","2":"12, 13, 17, 18, 20, 23, 26, 28, 38, 39, 41, 44","3":"2, 6–8, 10, 13, 15, 19, 21, 23"}},{"t":"case","label":"Harris v. McRae","cite":"448 U.S. 297","y":1980,"id":"1979/79-1268","sc":1,"op":5,"sum":"The Court held that states participating in the Medicaid program were not obligated to fund medically necessary abortions under Title XIX.","sumSrc":"Oyez","by":{"0":"33"}},{"t":"case","label":"Health & Hospital Corporation of Marion County v. Talevski","cite":"599 U.S. 166","y":2023,"id":"2022/21-806","sc":1,"op":36,"sum":"The provisions of the Federal Nursing Home Reform Act at issue unambiguously create rights enforceable under 42 U. S. C. §1983, and private enforcement under §1983 is compatible with the FNHRA’s remedial scheme.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"2–4, 14, 18–20, 22–25, 28, 34, 36, 40, 43, 46–47, 51, 55","1":"2, 3, 10, 12, 15, 18-20, 22, 24-27, 29, 30, 31","2":"2, 3, 11-15, 17, 18, 21-23, 25, 26, 28, 29, 33, 36, 37, 40-43","3":"1, 3, 7–8, 13, 15"}},{"t":"case","label":"Janus v. American Federation of State, County, and Municipal Employees, Council 31","cite":"585 U.S. 878","y":2018,"id":"2017/16-1466","sc":1,"sum":"The Court decided the State of Illinois’ extraction of agency fees from nonconsenting public-sector employees violates the First Amendment; Abood v. Detroit Bd. of Ed., 431 U.S. 209 (1977), which held otherwise, was overruled.","sumSrc":"Oyez","by":{"0":"52"}},{"t":"case","label":"Kennedy v. Bremerton School District","cite":"597 U.S. 507","y":2022,"id":"2021/21-418","sc":1,"sum":"The Free Exercise and Free Speech Clauses of the First Amendment protect an individual engaging in a personal religious observance from government reprisal; the Constitution neither mandates nor permits the government to suppress such religious expression.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"48–49"}},{"t":"case","label":"Kimble v. Marvel Entertainment, LLC","cite":"576 U.S. 446","y":2015,"id":"2014/13-720","sc":1,"sum":"The Court determined that its earlier decision in Brulotte v. Thys Co. , which held that a patentee cannot continue to receive royalties after the expiration of the patent, should be upheld.","sumSrc":"Oyez","by":{"0":"52"}},{"t":"case","label":"Lemon v. Kurtzman","cite":"403 U.S. 602","y":1971,"id":"1970/89","sc":1,"ar":1,"sum":"The Court found that Pennsylvania and Rhode Island statutes granting salary supplements to teachers at \"church-related educational institutions\" was unconstitutional for violating the Establishment Clause of the First Amendment. The case established the Lemon Test for determining if the government is becoming too involved in religious activities.","sumSrc":"Oyez","by":{"0":"48"}},{"t":"case","label":"Locke v. Davey","cite":"540 U.S. 712","y":2004,"id":"2003/02-1315","sc":1,"sum":"The Court ruled that a state does not violate the First Amendment's free exercise clause when it funds secular college majors but excludes devotional theology majors.","sumSrc":"Oyez","by":{"0":"50"}},{"t":"case","label":"Long Term Care Pharmacy Alliance v. Ferguson","cite":"362 F.3d 50","y":2004,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/362/50/","by":{"0":"52","2":"26"}},{"t":"case","label":"Loper Bright Enterprises v. Raimondo","cite":"603 U.S. 369","y":2024,"id":"2023/22-451","sc":1,"op":1,"sum":"The Administrative Procedure Act requires courts to exercise their independent judgment in deciding whether an agency has acted within its statutory authority, and courts may not defer to an agency interpretation of the law simply because a statute is ambiguous; Chevron U. S. A. Inc. v. Natural Resources Defense Council, Inc., 467 U. S. 837, is overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"50"}},{"t":"case","label":"Marx v. General Revenue Corp.","cite":"568 U.S. 371","y":2013,"id":"2012/11-1175","sc":1,"sum":"The Court held that the Federal Rules of Civil Procedure awards costs to the prevailing party unless a statute explicitly states otherwise.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Merrill Lynch, Pierce, Fenner & Smith, Inc. v. Curran","cite":"456 U.S. 353","y":1982,"id":"1981/80-203","sc":1,"sum":"A private party may maintain an action for damages caused by a violation of the CEA.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30"}},{"t":"case","label":"Midwest Foster Care & Adoption Association v. Kincade","cite":"712 F.3d 1190","y":2013,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/712/1190/","by":{"0":"34–35","1":"34","3":"18"}},{"t":"case","label":"Morse v. Republican Party of Virginia","cite":"517 U.S. 186","y":1996,"id":"1995/94-203","sc":1,"sum":"Yes and yes.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"National Federation of Independent Business v. Sebelius","cite":"567 U.S. 519","y":2012,"id":"2011/11-393","sc":1,"op":1,"sum":"Cases in which the Court held that the minimum coverage requirement of the Affordable Care Act was constitutional, that Congress had the power to enforce the taxation of most Americans that did not buy the minimum level of coverage, and that the federal government exceeded its power by pressuring States into accepting conditions that Congress could not impose directly by threatening to withhold all federal funding under Medicaid.","sumSrc":"Oyez","by":{"0":"17","2":"27"}},{"t":"case","label":"New York State Citizens’ Coalition for Children v. Poole","cite":"922 F.3d 69","y":2019,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/922/69/","op":3,"by":{"0":"51, 54","2":"43"}},{"t":"case","label":"O’Bannon v. Town Court Nursing Center","cite":"447 U.S. 773","y":1980,"id":"1979/78-1318","sc":1,"op":6,"sum":"The patients have no interest in receiving benefits for care in a particular facility that entitles them, as a matter of constitutional law, to a hearing before HEW and DPW can decertify that facility. Whatever legal rights the patients may have against the nursing home for failing to maintain its status as a qualified nursing home, the enforcement by HEW and DPW of their valid regulations did not directly affect …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"5","1":"34-16","2":"20"}},{"t":"case","label":"Pennhurst State School & Hospital v. Halderman","cite":"451 U.S. 1","y":1981,"id":"1980/79-1404","sc":1,"op":8,"ar":1,"sum":"Section 6010 does not create in favor of the mentally retarded any substantive rights to \"appropriate treatment\" in the \"least restrictive\" environment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16–18","1":"16, 17"}},{"t":"case","label":"Planned Parenthood of Greater Texas Family Planning & Preventive Health Services v. Smith","cite":"913 F.3d 551","y":2019,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/913/551/","by":{"0":"53"}},{"t":"case","label":"Planned Parenthood of Greater Texas Family Planning & Preventive Health Services, Inc. v. Kauffman","cite":"981 F.3d 347","y":2020,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/981/347/","op":1,"sum":"Explaining that Section 1320a-2 “did not inform the analysis” in Armstrong.","sumSrc":"brief:0","by":{"0":"5, 22, 36","1":"6","2":"24","3":"3, 19, 22–23"}},{"t":"case","label":"Romag Fasteners, Inc v. Fossil, Inc.","cite":"590 U.S. 212","y":2020,"id":"2019/18-1233","sc":1,"sum":"The Court held that under Section 35 of the Lanham Act, a plaintiff does not need to show willful infringement to receive an award of an infringer’s profits for a violation of Section 43(a).","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"Saint Anthony Hospital v. Whitehorn","cite":"100 F.4th 767","y":2024,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.4th/100/767/","sum":"Noting that Talevski did not “disapprove of Blessing” and claiming not to “see a fundamental difference between the Talevski/Gonzaga standard … and the first and third Blessing factors”.","sumSrc":"brief:0","by":{"0":"48"}},{"t":"case","label":"Saint Anthony Hospital v. Whitehorn","cite":"2024 WL 3561942","y":2024,"court":"7th Cir. July 24","by":{"0":"48"}},{"t":"case","label":"South Dakota v. Wayfair","cite":"585 U.S. 162","y":2018,"id":"2017/17-494","sc":1,"sum":"A case in which the Court overruled Quill Corp. v. North Dakota and National Bellas Hess, Inc. v. Department of Revenue of Illinois, holding that states may require sellers with no physical presence in the state to collect and remit sales tax for goods sold within the state.","sumSrc":"Oyez","by":{"0":"52"}},{"t":"case","label":"Suter v. Artist M.","cite":"503 U.S. 347","y":1992,"id":"1991/90-1488","sc":1,"op":6,"ar":12,"sum":"In a 7-to-2 decision, the Supreme Court held that the Adoption Assistance and Child Welfare Act of 1980 only required that a state have a plan for the administration of adoption and foster care programs in order to receive federal reimbursement, not that the plan be correctly carried out.","sumSrc":"Oyez","by":{"0":"40–41","2":"34-37","3":"21–22"}},{"t":"case","label":"United States for Benefit & on Behalf of Glynn v. Capeletti Brothers","cite":"621 F.2d 1309","y":1980,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/621/1309/","by":{"0":"19","3":"6"}},{"t":"case","label":"Universities Research Association, Inc. v. Coutu","cite":"450 U.S. 754","y":1981,"id":"1980/78-1945","sc":1,"sum":"The Davis-Bacon Act does not confer upon an employee a private right of action for back wages under a contract that has been administratively determined not to call for work subject to the Act and thus does not contain prevailing wage stipulations. Pp. 767-784. UNIVERSITIES RESEARCH ASSN. v. COUTU (a) While requiring that certain stipulations be placed in federal construction contracts for the benefit of mechanics …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19, 30–32, 34","2":"24","3":"6"}},{"t":"case","label":"Wilder v. Virginia Hospital Association","cite":"496 U.S. 498","y":1990,"id":"1989/88-2043","sc":1,"op":11,"ar":13,"sum":"In a 5-to-4 decision, the Court held that the Boren Amendment clearly established a right to reasonable and adequate reimbursement rates for the hospitals.","sumSrc":"Oyez","by":{"0":"13, 45, 51","1":"11, 12, 18","2":"26, 28, 36, 43","3":"2, 8"}},{"t":"case","label":"Wright v. City of Roanoke Redevelopment and Housing Authority","cite":"479 U.S. 418","y":1987,"id":"1986/85-5915","sc":1,"op":2,"sum":"Holding that public-housing tenants could use § 1983 to enforce a provision of the Housing Act of 1937 capping their rental payments.","sumSrc":"opinion","by":{"0":"17, 51","1":"12","2":"26, 28","3":"2, 8"}},{"t":"usc","label":"20 U.S.C. § 1232g","url":"https://www.law.cornell.edu/uscode/text/20/1232g","subs":["(b)(1)"],"stext":{"head":"§1232g. Family educational and privacy rights","paras":[[0,"(a) Conditions for availability of funds to educational agencies or institutions; inspection and review of education records; specific information to be made available; procedure for access to education records; reasonableness of time for such access; hearings; written explanations by parents; definitions"],[0,"(1)(A) No funds shall be made available under any applicable program to any educational agency or institution which has a policy of denying, or which effectively prevents, the parents of students who are or have been in attendance at a school of such agency or at such institution, as the case may be, the right to inspect and review the education records of their children. If any material or document in the education record of a student includes information on more than one student, the parents of one of such students shall have the right to inspect and review only such part of such material or document as relates to such student or to be informed of the specific information contained in such part of such material. Each educational agency or institution shall establish appropriate procedures for the granting of a request by parents for access to the education records of their children within a reasonable period of time, but in no case more than forty-five days after the request has been made."],[0,"(B) No funds under any applicable program shall be made available to any State educational agency (whether or not that agency is an educational agency or institution under this section) that has a policy of denying, or effectively prevents, the parents of students the right to inspect and review the education records maintained by the State educational agency on their children who are or have been in attendance at any school of an educational agency or institution that is subject to the provisions of this section."],[0,"(C) The first sentence of subparagraph (A) shall not operate to make available to students in institutions of postsecondary education the following materials:"],[1,"(i) financial records of the parents of the student or any information contained therein;"],[1,"(ii) confidential letters and statements of recommendation, which were placed in the education records prior to January 1, 1975, if such letters or statements are not used for purposes other than those for which they were specifically intended;"],[1,"(iii) if the student has signed a waiver of the student's right of access under this subsection in accordance with subparagraph (D), confidential recommendations—"],[2,"(I) respecting admission to any educational agency or institution,"],[2,"(II) respecting an application for employment, and"],[2,"(III) respecting the receipt of an honor or honorary recognition."],[0,"(D) A student or a person applying for admission may waive his right of access to confidential statements described in clause (iii) of subparagraph (C), except that such waiver shall apply to recommendations only if (i) the student is, upon request, notified of the names of all persons making confidential recommendations and (ii) such recommendations are used solely for the purpose for which they were specifically intended. Such waivers may not be required as a condition for admission to, receipt of financial aid from, or receipt of any other services or benefits from such agency or institution."],[0,"(2) No funds shall be made available under any applicable program to any educational agency or institution unless the parents of students who are or have been in attendance at a school of such agency or at such institution are provided an opportunity for a hearing by such agency or institution, in accordance with regulations of the Secretary, to challenge the content of such student's education records, in order to insure that the records are not inaccurate, misleading, or otherwise in violation of the privacy rights of students, and to provide an opportunity for the correction or deletion of any such inaccurate, misleading or otherwise inappropriate data contained therein and to insert into such records a written explanation of the parents respecting the content of such records."],[0,"(3) For the purposes of this section the term \"educational agency or institution\" means any public or private agency or institution which is the recipient of funds under any applicable program."],[0,"(4)(A) For the purposes of this section, the term \"education records\" means, except as may be provided otherwise in subparagraph (B), those records, files, documents, and other materials which—"],[1,"(i) contain information directly related to a student; and"],[1,"(ii) are maintained by an educational agency or institution or by a person acting for such agency or institution."],[0,"(B) The term \"education records\" does not include—"],[1,"(i) records of instructional, supervisory, and administrative personnel and educational personnel ancillary thereto which are in the sole possession of the maker thereof and which are not accessible or revealed to any other person except a substitute;"],[1,"(ii) records maintained by a law enforcement unit of the educational agency or institution that were created by that law enforcement unit for the purpose of law enforcement;"],[1,"(iii) in the case of persons who are employed by an educational agency or institution but who are not in attendance at such agency or institution, records made and maintained in the normal course of business which relate exclusively to such person in that person's capacity as an employee and are not available for use for any other purpose; or"],[1,"(iv) records on a student who is eighteen years of age or older, or is attending an institution of postsecondary education, which are made or maintained by a physician, psychiatrist, psychologist, or other recognized professional or paraprofessional acting in his professional or paraprofessional capacity, or assisting in that capacity, and which are made, maintained, or used only in connection with the provision of treatment to the student, and are not available to anyone other than persons providing such treatment, except that such records can be personally reviewed by a physician or other appropriate professional of the student's choice."],[0,"(5)(A) For the purposes of this section the term \"directory information\" relating to a student includes the following: the student's name, address, telephone listing, date and place of birth, major field of study, participation in officially recognized activities and sports, weight and height of members of athletic teams, dates of attendance, degrees and awards received, and the most recent previous educational agency or institution attended by the student."],[0,"(B) Any educational agency or institution making public directory information shall give public notice of the categories of information which it has designated as such information with respect to each student attending the institution or agency and shall allow a reasonable period of time after such notice has been given for a parent to inform the institution or agency that any or all of the information designated should not be released without the parent's prior consent."],[0,"(6) For the purposes of this section, the term \"student\" includes any person with respect to whom an educational agency or institution maintains education records or personally identifiable information, but does not include a person who has not been in attendance at such agency or institution."],[0,"(b) Release of education records; parental consent requirement; exceptions; compliance with judicial orders and subpoenas; audit and evaluation of federally-supported education programs; recordkeeping"],[0,"(1) No funds shall be made available under any applicable program to any educational agency or institution which has a policy or practice of permitting the release of education records (or personally identifiable information contained therein other than directory information, as defined in paragraph (5) of subsection (a)) of students without the written consent of their parents to any individual, agency, or organization, other than to the following—"],[1,"(A) other school officials, including teachers within the educational institution or local educational agency, who have been determined by such agency or institution to have legitimate educational interests, including the educational interests of the child for whom consent would otherwise be required;"],[1,"(B) officials of other schools or school systems in which the student seeks or intends to enroll, upon condition that the student's parents be notified of the transfer, receive a copy of the record if desired, and have an opportunity for a hearing to challenge the content of the record;"],[1,"(C)(i) authorized representatives of (I) the Comptroller General of the United States, (II) the Secretary, or (III) State educational authorities, under the conditions set forth in paragraph (3), or (ii) authorized representatives of the Attorney General for law enforcement purposes under the same conditions as apply to the Secretary under paragraph (3);"],[1,"(D) in connection with a student's application for, or receipt of, financial aid;"],[1,"(E) State and local officials or authorities to whom such information is specifically allowed to be reported or disclosed pursuant to State statute adopted—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/20/1232g?type=usc&year=mostrecent&link-type=html"},"head":"§1232g. Family educational and privacy rights","tname":"Education","by":{"0":"29–30, 34","1":"19, 21","2":"23, 23, 44"}},{"t":"usc","label":"20 U.S.C. § 1681","url":"https://www.law.cornell.edu/uscode/text/20/1681","subs":["(a)"],"stext":{"head":"§1681. Sex","paras":[[0,"(a) Prohibition against discrimination; exceptions"],[0,"No person in the United States shall, on the basis of sex, be excluded from participation in, be denied the benefits of, or be subjected to discrimination under any education program or activity receiving Federal financial assistance, except that:"],[0,"(1) Classes of educational institutions subject to prohibition"],[1,"in regard to admissions to educational institutions, this section shall apply only to institutions of vocational education, professional education, and graduate higher education, and to public institutions of undergraduate higher education;"],[0,"(2) Educational institutions commencing planned change in admissions"],[1,"in regard to admissions to educational institutions, this section shall not apply (A) for one year from June 23, 1972, nor for six years after June 23, 1972, in the case of an educational institution which has begun the process of changing from being an institution which admits only students of one sex to being an institution which admits students of both sexes, but only if it is carrying out a plan for such a change which is approved by the Secretary of Education or (B) for seven years from the date an educational institution begins the process of changing from being an institution which admits only students of only one sex to being an institution which admits students of both sexes, but only if it is carrying out a plan for such a change which is approved by the Secretary of Education, whichever is the later;"],[0,"(3) Educational institutions of religious organizations with contrary religious tenets"],[1,"this section shall not apply to an educational institution which is controlled by a religious organization if the application of this subsection would not be consistent with the religious tenets of such organization;"],[0,"(4) Educational institutions training individuals for military services or merchant marine"],[1,"this section shall not apply to an educational institution whose primary purpose is the training of individuals for the military services of the United States, or the merchant marine;"],[0,"(5) Public educational institutions with traditional and continuing admissions policy"],[1,"in regard to admissions this section shall not apply to any public institution of undergraduate higher education which is an institution that traditionally and continually from its establishment has had a policy of admitting only students of one sex;"],[0,"(6) Social fraternities or sororities; voluntary youth service organizations"],[1,"this section shall not apply to membership practices—"],[2,"(A) of a social fraternity or social sorority which is exempt from taxation under section 501(a) of title 26, the active membership of which consists primarily of students in attendance at an institution of higher education, or"],[2,"(B) of the Young Men's Christian Association, Young Women's Christian Association, Girl Scouts, Boy Scouts, Camp Fire Girls, and voluntary youth service organizations which are so exempt, the membership of which has traditionally been limited to persons of one sex and principally to persons of less than nineteen years of age;"],[0,"(7) Boy or Girl conferences"],[1,"this section shall not apply to—"],[2,"(A) any program or activity of the American Legion undertaken in connection with the organization or operation of any Boys State conference, Boys Nation conference, Girls State conference, or Girls Nation conference; or"],[2,"(B) any program or activity of any secondary school or educational institution specifically for—"],[3,"(i) the promotion of any Boys State conference, Boys Nation conference, Girls State conference, or Girls Nation conference; or"],[3,"(ii) the selection of students to attend any such conference;"],[0,"(8) Father-son or mother-daughter activities at educational institutions"],[1,"this section shall not preclude father-son or mother-daughter activities at an educational institution, but if such activities are provided for students of one sex, opportunities for reasonably comparable activities shall be provided for students of the other sex; and"],[0,"(9) Institution of higher education scholarship awards in \"beauty\" pageants"],[1,"this section shall not apply with respect to any scholarship or other financial assistance awarded by an institution of higher education to any individual because such individual has received such award in any pageant in which the attainment of such award is based upon a combination of factors related to the personal appearance, poise, and talent of such individual and in which participation is limited to individuals of one sex only, so long as such pageant is in compliance with other nondiscrimination provisions of Federal law."],[0,"(b) Preferential or disparate treatment because of imbalance in participation or receipt of Federal benefits; statistical evidence of imbalance"],[0,"Nothing contained in subsection (a) of this section shall be interpreted to require any educational institution to grant preferential or disparate treatment to the members of one sex on account of an imbalance which may exist with respect to the total number or percentage of persons of that sex participating in or receiving the benefits of any federally supported program or activity, in comparison with the total number or percentage of persons of that sex in any community, State, section, or other area: Provided, That this subsection shall not be construed to prevent the consideration in any hearing or proceeding under this chapter of statistical evidence tending to show that such an imbalance exists with respect to the participation in, or receipt of the benefits of, any such program or activity by the members of one sex."],[0,"(c) \"Educational institution\" defined"],[0,"For purposes of this chapter an educational institution means any public or private preschool, elementary, or secondary school, or any institution of vocational, professional, or higher education, except that in the case of an educational institution composed of more than one school, college, or department which are administratively separate units, such term means each such school, college, or department."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/20/1681?type=usc&year=mostrecent&link-type=html"},"head":"§1681. Sex","tname":"Education","by":{"0":"21, 26","2":"28"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"40 U.S.C. § 3142","url":"https://www.law.cornell.edu/uscode/text/40/3142","by":{"0":"31"}},{"t":"usc","label":"42 U.S.C. § 1320a-2","url":"https://www.law.cornell.edu/uscode/text/42/1320a-2","stext":{"head":"§1320a–2. Effect of failure to carry out State plan","paras":[[0,"In an action brought to enforce a provision of this chapter, such provision is not to be deemed unenforceable because of its inclusion in a section of this chapter requiring a State plan or specifying the required contents of a State plan. This section is not intended to limit or expand the grounds for determining the availability of private actions to enforce State plan requirements other than by overturning any such grounds applied in Suter v. Artist M., 112 S. Ct. 1360 (1992), but not applied in prior Supreme Court decisions respecting such enforceability; provided, however, that this section is not intended to alter the holding in Suter v. Artist M. that section 671(a)(15) of this title is not enforceable in a private right of action."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1320a-2?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§1320a–2. Effect of failure to carry out State plan","tname":"The Public Health and Welfare","by":{"0":"35, 40","1":"11, 15, 33, 34","2":"3, 14, 35, 37, 43","3":"16–17"}},{"t":"usc","label":"42 U.S.C. § 1396-1","url":"https://www.law.cornell.edu/uscode/text/42/1396-1","stext":{"head":"§1396–1. Appropriations","paras":[[0,"For the purpose of enabling each State, as far as practicable under the conditions in such State, to furnish (1) medical assistance on behalf of families with dependent children and of aged, blind, or disabled individuals, whose income and resources are insufficient to meet the costs of necessary medical services, and (2) rehabilitation and other services to help such families and individuals attain or retain capability for independence or self-care, there is hereby authorized to be appropriated for each fiscal year a sum sufficient to carry out the purposes of this subchapter. The sums made available under this section shall be used for making payments to States which have submitted, and had approved by the Secretary, State plans for medical assistance."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1396-1?type=usc&year=mostrecent&link-type=html"},"head":"§1396–1. Appropriations","tname":"The Public Health and Welfare","by":{"0":"4","1":"1, 1","2":"4"}},{"t":"usc","label":"42 U.S.C. § 1396a","url":"https://www.law.cornell.edu/uscode/text/42/1396a","subs":["(a)","(a)(1)","(a)(3)","(a)(4)","(a)(6)","(a)(10)(A)","(a)(12)","(a)(13)(A)(1982)","(a)(22)","(a)(23)","(a)(23)(A)","(a)(24)","(a)(26)","(a)(28)(A)","(a)(30)(A)","(a)(32)","(a)(53)","(a)(58)","(a)(59)","(a)(71)","(a)(84)(2024)","(b)","(p)(1)","(a)(10)(A)(ii)","(a)(17)","(a)(23)(B)","(a)(47)(A)","(kk)(8)(B)(ii)"],"stext":{"head":"§1396a. State plans for medical assistance","paras":[[0,"(a) Contents"],[0,"A State plan for medical assistance must—"],[1,"(1) provide that it shall be in effect in all political subdivisions of the State, and, if administered by them, be mandatory upon them;"],[1,"(2) provide for financial participation by the State equal to not less than 40 per centum of the non-Federal share of the expenditures under the plan with respect to which payments under section 1396b of this title are authorized by this subchapter; and, effective July 1, 1969, provide for financial participation by the State equal to all of such non-Federal share or provide for distribution of funds from Federal or State sources, for carrying out the State plan, on an equalization or other basis which will assure that the lack of adequate funds from local sources will not result in lowering the amount, duration, scope, or quality of care and services available under the plan;"],[1,"(3) provide for granting an opportunity for a fair hearing before the State agency to any individual whose claim for medical assistance under the plan is denied or is not acted upon with reasonable promptness;"],[1,"(4) provide (A) such methods of administration (including methods relating to the establishment and maintenance of personnel standards on a merit basis, except that the Secretary shall exercise no authority with respect to the selection, tenure of office, and compensation of any individual employed in accordance with such methods, including provision for utilization of professional medical personnel in the administration and, where administered locally, supervision of administration of the plan, and, subject to section 1396b(i) of this title, including a specification that the single State agency described in paragraph (5) will ensure necessary transportation for beneficiaries under the State plan to and from providers and a description of the methods that such agency will use to ensure such transportation) as are found by the Secretary to be necessary for the proper and efficient operation of the plan, (B) for the training and effective use of paid subprofessional staff, with particular emphasis on the full-time or part-time employment of recipients and other persons of low income, as community service aides, in the administration of the plan and for the use of nonpaid or partially paid volunteers in a social service volunteer program in providing services to applicants and recipients and in assisting any advisory committees established by the State agency, (C) that each State or local officer, employee, or independent contractor who is responsible for the expenditure of substantial amounts of funds under the State plan, each individual who formerly was such an officer, employee, or contractor, and each partner of such an officer, employee, or contractor shall be prohibited from committing any act, in relation to any activity under the plan, the commission of which, in connection with any activity concerning the United States Government, by an officer or employee of the United States Government, an individual who was such an officer or employee, or a partner of such an officer or employee is prohibited by section 207 or 208 of title 18, and (D) that each State or local officer, employee, or independent contractor who is responsible for selecting, awarding, or otherwise obtaining items and services under the State plan shall be subject to safeguards against conflicts of interest that are at least as stringent as the safeguards that apply under chapter 21 of title 41 to persons described in section 2102(a)(3) of title 41;"],[1,"(5) either provide for the establishment or designation of a single State agency to administer or to supervise the administration of the plan; or provide for the establishment or designation of a single State agency to administer or to supervise the administration of the plan, except that the determination of eligibility for medical assistance under the plan shall be made by the State or local agency administering the State plan approved under subchapter I or XVI (insofar as it relates to the aged) if the State is eligible to participate in the State plan program established under subchapter XVI, or by the agency or agencies administering the supplemental security income program established under subchapter XVI or the State plan approved under part A of subchapter IV if the State is not eligible to participate in the State plan program established under subchapter XVI;"],[1,"(6) provide that the State agency will make such reports, in such form and containing such information, as the Secretary may from time to time require, and comply with such provisions as the Secretary may from time to time find necessary to assure the correctness and verification of such reports;"],[1,"(7) provide—"],[2,"(A) safeguards which restrict the use or disclosure of information concerning applicants and recipients to purposes directly connected with—"],[3,"(i) the administration of the plan; and"],[3,"(ii) the exchange of information necessary to certify or verify the certification of eligibility of children for free or reduced price breakfasts under the Child Nutrition Act of 1966 [42 U.S.C. 1771 et seq.] and free or reduced price lunches under the Richard B. Russell National School Lunch Act [42 U.S.C. 1751 et seq.], in accordance with section 9(b) of that Act [42 U.S.C. 1758(b)], using data standards and formats established by the State agency; and"],[2,"(B) that, notwithstanding the Express Lane option under subsection (e)(13), the State may enter into an agreement with the State agency administering the school lunch program established under the Richard B. Russell National School Lunch Act under which the State shall establish procedures to ensure that—"],[3,"(i) a child receiving medical assistance under the State plan under this subchapter whose family income does not exceed 133 percent of the poverty line (as defined in section 9902(2) of this title, including any revision required by such section), as determined without regard to any expense, block, or other income disregard, applicable to a family of the size involved, may be certified as eligible for free lunches under the Richard B. Russell National School Lunch Act and free breakfasts under the Child Nutrition Act of 1966 without further application; and"],[3,"(ii) the State agencies responsible for administering the State plan under this subchapter, and for carrying out the school lunch program established under the Richard B. Russell National School Lunch Act (42 U.S.C. 1751 et seq.) or the school breakfast program established by section 4 of the Child Nutrition Act of 1966 (42 U.S.C. 1773), cooperate in carrying out paragraphs (3)(F) and (15) of section 9(b) of that Act [42 U.S.C. 1758(b)];"],[1,"(8) provide that all individuals wishing to make application for medical assistance under the plan shall have opportunity to do so, and that such assistance shall be furnished with reasonable promptness to all eligible individuals;"],[1,"(9) provide—"],[2,"(A) that the State health agency, or other appropriate State medical agency (whichever is utilized by the Secretary for the purpose specified in the first sentence of section 1395aa(a) of this title), shall be responsible for establishing and maintaining health standards for private or public institutions in which recipients of medical assistance under the plan may receive care or services,"],[2,"(B) for the establishment or designation of a State authority or authorities which shall be responsible for establishing and maintaining standards, other than those relating to health, for such institutions,"],[2,"(C) that any laboratory services paid for under such plan must be provided by a laboratory which meets the applicable requirements of section 1395x(e)(9) of this title or paragraphs (16) and (17) of section 1395x(s) of this title, or, in the case of a laboratory which is in a rural health clinic, of section 1395x(aa)(2)(G) of this title, and"],[2,"(D) that the State maintain a consumer-oriented website providing useful information to consumers regarding all skilled nursing facilities and all nursing facilities in the State, including for each facility, Form 2567 State inspection reports (or a successor form), complaint investigation reports, the facility's plan of correction, and such other information that the State or the Secretary considers useful in assisting the public to assess the quality of long term care options and the quality of care provided by individual facilities;"],[1,"(10) provide—"],[2,"(A) for making medical assistance available, including at least the care and services listed in paragraphs (1) through (5), (13)(B), (17), (21), (28), (29), and (30) of section 1396d(a) of this title, to—"],[3,"(i) all individuals—"],[4,"(I) who are receiving aid or assistance under any plan of the State approved under subchapter I, X, XIV, or XVI, or part A or part E of subchapter IV (including individuals eligible under this subchapter by reason of section 602(a)(37),1 606(h),1 or 673(b) of this title, or considered by the State to be receiving such aid as authorized under section 682(e)(6)1 of this title),"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1396a?type=usc&year=mostrecent&link-type=html"},"op":3,"ar":1,"head":"§1396a. State plans for medical assistance","tname":"The Public Health and Welfare","by":{"0":"1, 3, 5–6, 20–22, 32, 35, 37–40, 42–44","1":"5, 6, 22, 26, 27, 3-6, 13, 22-25, 28, 32, 23, 22, 28, 31, 5, 23, 5, 5, 27, 21, 3, 1, 3, 4, 7-15, 23-27, 29, 3, 6, 12, 15, 22, 25, 3, 23, 28, 26, 21, 26, 28, 28, 22, 23, 23, 28, 1, 5, 26, 7","2":"33, 34, 37, 38, 44, 44, 45, 38, 38, 4, 38, 26, 28, 4, 1, 2, 4, 6, 8, 12, 13, 16, 19-22, 24, 27, 29, 34, 35, 37, 41, 47, 5, 19, 21, 27, 33, 38, 38, 38, 45, 48","3":"2, 4, 6, 9–11, 16–17, 20, 22"}},{"t":"usc","label":"42 U.S.C. § 1396c","url":"https://www.law.cornell.edu/uscode/text/42/1396c","subs":["(2)"],"stext":{"head":"§1396c. Operation of State plans","paras":[[0,"If the Secretary, after reasonable notice and opportunity for hearing to the State agency administering or supervising the administration of the State plan approved under this subchapter, finds—"],[1,"(1) that the plan has been so changed that it no longer complies with the provisions of section 1396a of this title; or"],[1,"(2) that in the administration of the plan there is a failure to comply substantially with any such provision;"],[0,"the Secretary shall notify such State agency that further payments will not be made to the State (or, in his discretion, that payments will be limited to categories under or parts of the State plan not affected by such failure), until the Secretary is satisfied that there will no longer be any such failure to comply. Until he is so satisfied he shall make no further payments to such State (or shall limit payments to categories under or parts of the State plan not affected by such failure)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1396c?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1396c. Operation of State plans","tname":"The Public Health and Welfare","by":{"0":"2, 4, 33, 34","1":"1, 6, 24","2":"4, 33, 35, 44"}},{"t":"usc","label":"42 U.S.C. § 1396r","url":"https://www.law.cornell.edu/uscode/text/42/1396r","subs":["(c)","(c)(1)(A)(ii)","(c)(1)(A)","(c)(2)(A)","(c)(2)(B)","(h)(8)","(c)(2)","(h)","(h)(4)"],"stext":{"head":"§1396r. Requirements for nursing facilities","paras":[[0,"(a) \"Nursing facility\" defined"],[0,"In this subchapter, the term \"nursing facility\" means an institution (or a distinct part of an institution) which—"],[1,"(1) is primarily engaged in providing to residents—"],[2,"(A) skilled nursing care and related services for residents who require medical or nursing care,"],[2,"(B) rehabilitation services for the rehabilitation of injured, disabled, or sick persons, or"],[2,"(C) on a regular basis, health-related care and services to individuals who because of their mental or physical condition require care and services (above the level of room and board) which can be made available to them only through institutional facilities,"],[1,"and is not primarily for the care and treatment of mental diseases;"],[1,"(2) has in effect a transfer agreement (meeting the requirements of section 1395x(l) of this title) with one or more hospitals having agreements in effect under section 1395cc of this title; and"],[1,"(3) meets the requirements for a nursing facility described in subsections (b), (c), and (d) of this section."],[0,"Such term also includes any facility which is located in a State on an Indian reservation and is certified by the Secretary as meeting the requirements of paragraph (1) and subsections (b), (c), and (d)."],[0,"(b) Requirements relating to provision of services"],[0,"(1) Quality of life"],[0,"(A) In general"],[2,"A nursing facility must care for its residents in such a manner and in such an environment as will promote maintenance or enhancement of the quality of life of each resident."],[0,"(B) Quality assessment and assurance"],[2,"A nursing facility must maintain a quality assessment and assurance committee, consisting of the director of nursing services, a physician designated by the facility, and at least 3 other members of the facility's staff, which (i) meets at least quarterly to identify issues with respect to which quality assessment and assurance activities are necessary and (ii) develops and implements appropriate plans of action to correct identified quality deficiencies. A State or the Secretary may not require disclosure of the records of such committee except insofar as such disclosure is related to the compliance of such committee with the requirements of this subparagraph."],[0,"(2) Scope of services and activities under plan of care"],[1,"A nursing facility must provide services and activities to attain or maintain the highest practicable physical, mental, and psychosocial well-being of each resident in accordance with a written plan of care which—"],[2,"(A) describes the medical, nursing, and psychosocial needs of the resident and how such needs will be met;"],[2,"(B) is initially prepared, with the participation to the extent practicable of the resident or the resident's family or legal representative, by a team which includes the resident's attending physician and a registered professional nurse with responsibility for the resident; and"],[2,"(C) is periodically reviewed and revised by such team after each assessment under paragraph (3)."],[0,"(3) Residents' assessment"],[0,"(A) Requirement"],[2,"A nursing facility must conduct a comprehensive, accurate, standardized, reproducible assessment of each resident's functional capacity, which assessment—"],[3,"(i) describes the resident's capability to perform daily life functions and significant impairments in functional capacity;"],[3,"(ii) is based on a uniform minimum data set specified by the Secretary under subsection (f)(6)(A);"],[3,"(iii) uses an instrument which is specified by the State under subsection (e)(5); and"],[3,"(iv) includes the identification of medical problems."],[0,"(B) Certification"],[0,"(i) In general"],[3,"Each such assessment must be conducted or coordinated (with the appropriate participation of health professionals) by a registered professional nurse who signs and certifies the completion of the assessment. Each individual who completes a portion of such an assessment shall sign and certify as to the accuracy of that portion of the assessment."],[0,"(ii) Penalty for falsification"],[3,"(I) An individual who willfully and knowingly certifies under clause (i) a material and false statement in a resident assessment is subject to a civil money penalty of not more than $1,000 with respect to each assessment."],[3,"(II) An individual who willfully and knowingly causes another individual to certify under clause (i) a material and false statement in a resident assessment is subject to a civil money penalty of not more than $5,000 with respect to each assessment."],[3,"(III) The provisions of section 1320a–7a of this title (other than subsections (a) and (b)) shall apply to a civil money penalty under this clause in the same manner as such provisions apply to a penalty or proceeding under section 1320a–7a(a) of this title."],[0,"(iii) Use of independent assessors"],[3,"If a State determines, under a survey under subsection (g) or otherwise, that there has been a knowing and willful certification of false assessments under this paragraph, the State may require (for a period specified by the State) that resident assessments under this paragraph be conducted and certified by individuals who are independent of the facility and who are approved by the State."],[0,"(C) Frequency"],[0,"(i) In general"],[3,"Such an assessment must be conducted—"],[4,"(I) promptly upon (but no later than 14 days after the date of) admission for each individual admitted on or after October 1, 1990, and by not later than October 1, 1991, for each resident of the facility on that date;"],[4,"(II) promptly after a significant change in the resident's physical or mental condition; and"],[4,"(III) in no case less often than once every 12 months."],[0,"(ii) Resident review"],[3,"The nursing facility must examine each resident no less frequently than once every 3 months and, as appropriate, revise the resident's assessment to assure the continuing accuracy of the assessment."],[0,"(D) Use"],[2,"The results of such an assessment shall be used in developing, reviewing, and revising the resident's plan of care under paragraph (2)."],[0,"(E) Coordination"],[2,"Such assessments shall be coordinated with any State-required preadmission screening program to the maximum extent practicable in order to avoid duplicative testing and effort. In addition, a nursing facility shall notify the State mental health authority or State mental retardation or developmental disability authority, as applicable, promptly after a significant change in the physical or mental condition of a resident who is mentally ill or mentally retarded."],[0,"(F) Requirements relating to preadmission screening for mentally ill and mentally retarded individuals"],[2,"Except as provided in clauses (ii) and (iii) of subsection (e)(7)(A), a nursing facility must not admit, on or after January 1, 1989, any new resident who—"],[3,"(i) is mentally ill (as defined in subsection (e)(7)(G)(i)) unless the State mental health authority has determined (based on an independent physical and mental evaluation performed by a person or entity other than the State mental health authority) prior to admission that, because of the physical and mental condition of the individual, the individual requires the level of services provided by a nursing facility, and, if the individual requires such level of services, whether the individual requires specialized services for mental illness, or"],[3,"(ii) is mentally retarded (as defined in subsection (e)(7)(G)(ii)) unless the State mental retardation or developmental disability authority has determined prior to admission that, because of the physical and mental condition of the individual, the individual requires the level of services provided by a nursing facility, and, if the individual requires such level of services, whether the individual requires specialized services for mental retardation."],[2,"A State mental health authority and a State mental retardation or developmental disability authority may not delegate (by subcontract or otherwise) their responsibilities under this subparagraph to a nursing facility (or to an entity that has a direct or indirect affiliation or relationship with such a facility)."],[0,"(4) Provision of services and activities"],[0,"(A) In general"],[2,"To the extent needed to fulfill all plans of care described in paragraph (2), a nursing facility must provide (or arrange for the provision of)—"],[3,"(i) nursing and related services and specialized rehabilitative services to attain or maintain the highest practicable physical, mental, and psychosocial well-being of each resident;"],[3,"(ii) medically-related social services to attain or maintain the highest practicable physical, mental, and psychosocial well-being of each resident;"],[3,"(iii) pharmaceutical services (including procedures that assure the accurate acquiring, receiving, dispensing, and administering of all drugs and biologicals) to meet the needs of each resident;"],[3,"(iv) dietary services that assure that the meals meet the daily nutritional and special dietary needs of each resident;"],[3,"(v) an on-going program, directed by a qualified professional, of activities designed to meet the interests and the physical, mental, and psychosocial well-being of each resident;"],[3,"(vi) routine dental services (to the extent covered under the State plan) and emergency dental services to meet the needs of each resident; and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1396r?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1396r. Requirements for nursing facilities","tname":"The Public Health and Welfare","by":{"0":"3, 21–25, 43","1":"25, 3, 22, 20, 20, 20, 20, 3","2":"22, 11, 22, 26, 28, 22, 28, 11, 22, 22, 29, 36","3":"6, 9, 11, 16"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","stext":{"head":"§1983. Civil action for deprivation of rights","paras":[[0,"Every person who, under color of any statute, ordinance, regulation, custom, or usage, of any State or Territory or the District of Columbia, subjects, or causes to be subjected, any citizen of the United States or other person within the jurisdiction thereof to the deprivation of any rights, privileges, or immunities secured by the Constitution and laws, shall be liable to the party injured in an action at law, suit in equity, or other proper proceeding for redress, except that in any action brought against a judicial officer for an act or omission taken in such officer's judicial capacity, injunctive relief shall not be granted unless a declaratory decree was violated or declaratory relief was unavailable. For the purposes of this section, any Act of Congress applicable exclusively to the District of Columbia shall be considered to be a statute of the District of Columbia."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1983?type=usc&year=mostrecent&link-type=html"},"op":184,"ar":8,"head":"§1983. Civil action for deprivation of rights","tname":"The Public Health and Welfare","by":{"0":"18, 47, 51","1":"1-4, 7-9, 11-21, 23, 24, 27-31, 34, 35","2":"2, 9-12, 14-18, 24-26, 28, 33, 34, 36, 37, 39-43, 45-47"}},{"t":"usc","label":"42 U.S.C. § 2000d","url":"https://www.law.cornell.edu/uscode/text/42/2000d","stext":{"head":"§2000d. Prohibition against exclusion from participation in, denial of benefits of, and discrimination under federally assisted programs on ground of race, color, or national origin","paras":[[0,"No person in the United States shall, on the ground of race, color, or national origin, be excluded from participation in, be denied the benefits of, or be subjected to discrimination under any program or activity receiving Federal financial assistance."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000d?type=usc&year=mostrecent&link-type=html"},"head":"§2000d. Prohibition against exclusion from participation in, denial of benefits of, and discrimination under federally assisted programs on ground of race, color, or national origin","tname":"The Public Health and Welfare","by":{"0":"26","2":"28"}},{"t":"usc","label":"42 U.S.C. § 671","url":"https://www.law.cornell.edu/uscode/text/42/671","subs":["(a)(12)","(a)(15)(1988)"],"stext":{"head":"§671. State plan for foster care and adoption assistance","paras":[[0,"(a) Requisite features of State plan"],[0,"In order for a State to be eligible for payments under this part, it shall have a plan approved by the Secretary which—"],[1,"(1) provides for foster care maintenance payments in accordance with section 672 of this title, adoption assistance in accordance with section 673 of this title, and, at the option of the State, services or programs specified in subsection (e)(1) of this section for children who are candidates for foster care or who are pregnant or parenting foster youth and the parents or kin caregivers of the children, in accordance with the requirements of that subsection;"],[1,"(2) provides that the State agency responsible for administering the program authorized by subpart 1 of part B of this subchapter shall administer, or supervise the administration of, the program authorized by this part;"],[1,"(3) provides that the plan shall be in effect in all political subdivisions of the State, and, if administered by them, be mandatory upon them;"],[1,"(4) provides that the State shall assure that the programs at the local level assisted under this part will be coordinated with the programs at the State or local level assisted under parts A and B of this subchapter, under division A 1 of subchapter XX of this chapter, and under any other appropriate provision of Federal law;"],[1,"(5) provides that the State will, in the administration of its programs under this part, use such methods relating to the establishment and maintenance of personnel standards on a merit basis as are found by the Secretary to be necessary for the proper and efficient operation of the programs, except that the Secretary shall exercise no authority with respect to the selection, tenure of office, or compensation of any individual employed in accordance with such methods;"],[1,"(6) provides that the State agency referred to in paragraph (2) (hereinafter in this part referred to as the \"State agency\") will make such reports, in such form and containing such information as the Secretary may from time to time require, and comply with such provisions as the Secretary may from time to time find necessary to assure the correctness and verification of such reports;"],[1,"(7) provides that the State agency will monitor and conduct periodic evaluations of activities carried out under this part;"],[1,"(8) subject to subsection (c), provides safeguards which restrict the use of or disclosure of information concerning individuals assisted under the State plan to purposes directly connected with (A) the administration of the plan of the State approved under this part, the plan or program of the State under part A, B, or D of this subchapter or under subchapter I, V, X, XIV, XVI (as in effect in Puerto Rico, Guam, and the Virgin Islands), XIX, or XX, the program established by subchapter II, or the supplemental security income program established by subchapter XVI, (B) any investigation, prosecution, or criminal or civil proceeding, conducted in connection with the administration of any such plan or program, (C) the administration of any other Federal or federally assisted program which provides assistance, in cash or in kind, or services, directly to individuals on the basis of need, (D) any audit or similar activity conducted in connection with the administration of any such plan or program by any governmental agency which is authorized by law to conduct such audit or activity, and (E) reporting and providing information pursuant to paragraph (9) to appropriate authorities with respect to known or suspected child abuse or neglect; and the safeguards so provided shall prohibit disclosure, to any committee or legislative body (other than an agency referred to in clause (D) with respect to an activity referred to in such clause), of any information which identifies by name or address any such applicant or recipient; except that nothing contained herein shall preclude a State from providing standards which restrict disclosures to purposes more limited than those specified herein, or which, in the case of adoptions, prevent disclosure entirely;"],[1,"(9) provides that the State agency will—"],[2,"(A) report to an appropriate agency or official, known or suspected instances of physical or mental injury, sexual abuse or exploitation, or negligent treatment or maltreatment of a child receiving aid under part B or this part under circumstances which indicate that the child's health or welfare is threatened thereby;"],[2,"(B) provide such information with respect to a situation described in subparagraph (A) as the State agency may have; and"],[2,"(C) not later than—"],[3,"(i) 1 year after September 29, 2014, demonstrate to the Secretary that the State agency has developed, in consultation with State and local law enforcement, juvenile justice systems, health care providers, education agencies, and organizations with experience in dealing with at-risk children and youth, policies and procedures (including relevant training for caseworkers) for identifying, documenting in agency records, and determining appropriate services with respect to—"],[4,"(I) any child or youth over whom the State agency has responsibility for placement, care, or supervision and who the State has reasonable cause to believe is, or is at risk of being, a sex trafficking victim (including children for whom a State child welfare agency has an open case file but who have not been removed from the home, children who have run away from foster care and who have not attained 18 years of age or such older age as the State has elected under section 675(8) of this title, and youth who are not in foster care but are receiving services under section 677 of this title); and"],[4,"(II) at the option of the State, any individual who has not attained 26 years of age, without regard to whether the individual is or was in foster care under the responsibility of the State; and"],[3,"(ii) 2 years after September 29, 2014, demonstrate to the Secretary that the State agency is implementing the policies and procedures referred to in clause (i)."],[1,"(10) provides—"],[2,"(A) for the establishment or designation of a State authority or authorities that shall be responsible for establishing and maintaining standards for foster family homes and child care institutions which are reasonably in accord with recommended standards of national organizations concerned with standards for the institutions or homes, including standards related to admission policies, safety, sanitation, and protection of civil rights, and which shall permit use of the reasonable and prudent parenting standard;"],[2,"(B) that the standards established pursuant to subparagraph (A) shall be applied by the State to any foster family home or child care institution receiving funds under this part or part B and shall require, as a condition of each contract entered into by a child care institution to provide foster care, the presence on-site of at least 1 official who, with respect to any child placed at the child care institution, is designated to be the caregiver who is authorized to apply the reasonable and prudent parent standard to decisions involving the participation of the child in age or developmentally-appropriate activities, and who is provided with training in how to use and apply the reasonable and prudent parent standard in the same manner as prospective foster parents are provided the training pursuant to paragraph (24);"],[2,"(C) that the standards established pursuant to subparagraph (A) shall include policies related to the liability of foster parents and private entities under contract by the State involving the application of the reasonable and prudent parent standard, to ensure appropriate liability for caregivers when a child participates in an approved activity and the caregiver approving the activity acts in accordance with the reasonable and prudent parent standard; and"],[2,"(D) that a waiver of any standards established pursuant to subparagraph (A) may be made only on a case-by-case basis for nonsafety standards (as determined by the State) in relative foster family homes for specific children in care;"],[1,"(11) provides for periodic review of the standards referred to in the preceding paragraph and amounts paid as foster care maintenance payments and adoption assistance to assure their continuing appropriateness;"],[1,"(12) provides for granting an opportunity for a fair hearing before the State agency to any individual whose claim for benefits available pursuant to this part is denied or is not acted upon with reasonable promptness;"],[1,"(13) provides that the State shall arrange for a periodic and independently conducted audit of the programs assisted under this part and part B of this subchapter, which shall be conducted no less frequently than once every three years;"],[1,"(14) provides (A) specific goals (which shall be established by State law on or before October 1, 1982) for each fiscal year (commencing with the fiscal year which begins on October 1, 1983) as to the maximum number of children (in absolute numbers or as a percentage of all children in foster care with respect to whom assistance under the plan is provided during such year) who, at any time during such year, will remain in foster care after having been in such care for a period in excess of twenty-four months, and (B) a description of the steps which will be taken by the State to achieve such goals;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/671?type=usc&year=mostrecent&link-type=html"},"head":"§671. State plan for foster care and adoption assistance","tname":"The Public Health and Welfare","by":{"0":"41","1":"29, 29","2":"34, 36"}},{"t":"reg","label":"42 C.F.R. § 1002.213","url":"https://www.ecfr.gov/current/title-42/section-1002.213","by":{"0":"6, 42","2":"45","3":"22–23"}},{"t":"reg","label":"42 C.F.R. § 430.12","url":"https://www.ecfr.gov/current/title-42/section-430.12","subs":["(c)"],"by":{"0":"33","2":"4"}},{"t":"const","label":"Amendment I","clauses":[["establishment","Establishment Clause"],["free-exercise","Free Exercise Clause"],["free-speech","Free Speech Clause"],["free-press","Free Press Clause"],["assembly-petition","Assembly, Petition and Association"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"0":"21","2":"28"}},{"t":"const","label":"Amendment V","clauses":[["grand-jury","Grand Jury Clause"],["double-jeopardy","Double Jeopardy Clause"],["self-incrimination","Self-Incrimination Clause"],["due-process-5","Due Process Clause (Fifth Amendment)"],["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"0":"27","2":"28"}},{"t":"case","label":"ASW v. Oregon","cite":"424 F.3d 970","y":2005,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/424/970/","op":1,"sum":"Finding Section 1983-enforceable right.","sumSrc":"brief:1","by":{"1":"29"}},{"t":"case","label":"Alexander v. Choate","cite":"469 U.S. 287","y":1985,"id":"1984/83-727","sc":1,"sum":"Assuming that § 504 or its implementing regulations reach some claims of disparate-impact discrimination, the effect of Tennessee's reduction in annual inpatient hospital coverage is not among them.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"17"}},{"t":"case","label":"Aliser v. SEIU California","cite":"419 F. Supp. 3d 1161","y":2019,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/419/1161/","sum":"Holding that paragraph (a)(32) “does not create an individually enforceable right”.","sumSrc":"brief:1","by":{"1":"29"}},{"t":"case","label":"Briggs v. Bremby","cite":"792 F.3d 239","y":2015,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/792/239/","sum":"Finding Section 1983-enforceable right.","sumSrc":"brief:1","by":{"1":"29"}},{"t":"case","label":"City of Rancho Palos Verdes v. Abrams","cite":"544 U.S. 113","y":2005,"id":"2004/03-1601","sc":1,"op":1,"ar":1,"sum":"The Court held that Abrams could not enforce the limitations of the Telecommunications Act on local authorities through federal liability law, because the act provides its own judicial remedy. Congress could not have meant the judicial remedy expressly authorized by the Telecommunications Act to co-exist with an alternative remedy.","sumSrc":"Oyez","by":{"1":"16","2":"17, 42, 43"}},{"t":"case","label":"Dellmuth v. Muth","cite":"491 U.S. 223","y":1989,"id":"1988/87-1855","sc":1,"by":{"1":"17"}},{"t":"case","label":"FAA v. Cooper","cite":"566 U.S. 284","y":2012,"id":"2011/10-1024","sc":1,"sum":"The Court held that the Privacy Act of 1974 does not cover mental and emotional distress under \"actual damages.\"","sumSrc":"Oyez","by":{"1":"11","2":"25","3":"8"}},{"t":"case","label":"Goldberg v. Kelly","cite":"397 U.S. 254","y":1970,"id":"1969/62","sc":1,"op":6,"sum":"In a 5-to-3 decision, the Court held that states must afford public aid recipients a pre-termination evidentiary hearing before discontinuing their aid.","sumSrc":"Oyez","by":{"1":"31, 32"}},{"t":"case","label":"Gregory v. Ashcroft","cite":"501 U.S. 452","y":1991,"id":"1990/90-50","sc":1,"op":1,"sum":"In addition to emphasizing Missouri's, or any other state's, Tenth Amendment right to define the qualifications of its highest state officials, the Court held that the regulations of the ADEA did not apply to \"policy-making\" appointees such as state court judges.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"King v. Burwell","cite":"576 U.S. 473","y":2015,"id":"2014/14-114","sc":1,"sum":"The Court determined that the plain language of the Affordable Care Act extended tax credits to federally-created exchanges as well as those the states created.","sumSrc":"Oyez","by":{"1":"33"}},{"t":"case","label":"Maine v. Thiboutot","cite":"448 U.S. 1","y":1980,"id":"1979/79-838","sc":1,"op":8,"sum":"Yes to both. Section 1983 encompasses claims based on purely statutory violations of federal law, and section 1988 authorizes attorney's fees to the prevailing party in such actions, whether brought in federal or state court.","sumSrc":"AI-generated brief","by":{"1":"16","2":"17"}},{"t":"case","label":"Planned Parenthood Arizona Inc. v. Betlach","cite":"727 F.3d 960","y":2013,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/727/960/","op":1,"by":{"1":"19","2":"24"}},{"t":"case","label":"Shakhnes v. Berlin","cite":"689 F.3d 244","y":2012,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/689/244/","sum":"Finding a privately enforceable right in paragraph (a)(3).","sumSrc":"brief:1","by":{"1":"29"}},{"t":"case","label":"Turkiye Halk Bankasi A.S. v. United States","cite":"598 U.S. 264","y":2023,"id":"2022/21-1450","sc":1,"sum":"The District Court has jurisdiction of this criminal prosecution under 18 U. S. C. §3231, and the Foreign Sovereign Immunities Act’s comprehensive scheme governing claims of immunity in civil actions against foreign states and their instrumentalities does not cover criminal cases.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"32"}},{"t":"law","label":"Pub. L. No. 105-33","url":"https://www.govinfo.gov/link/plaw/105/public/33","by":{"1":"21"}},{"t":"usc","label":"7 U.S.C. § 2011","url":"https://www.law.cornell.edu/uscode/text/7/2011","by":{"1":"29"}},{"t":"usc","label":"7 U.S.C. § 2020","url":"https://www.law.cornell.edu/uscode/text/7/2020","subs":["(e)(3)"],"by":{"1":"29"}},{"t":"law","label":"Pub. L. No. 118-47","url":"https://www.govinfo.gov/link/plaw/118/public/47","by":{"1":"7","2":"7"}},{"t":"usc","label":"42 U.S.C. § 301","url":"https://www.law.cornell.edu/uscode/text/42/301","stext":{"head":"§301. Authorization of appropriations","paras":[[0,"For the purpose of enabling each State, as far as practicable under the conditions in such State, to furnish financial assistance to aged needy individuals, there is hereby authorized to be appropriated for each fiscal year a sum sufficient to carry out the purposes of this subchapter. The sums made available under this section shall be used for making payments to States which have submitted, and had approved by the Secretary of Health and Human Services (hereinafter referred to as the \"Secretary\"), State plans for old-age assistance."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/301?type=usc&year=mostrecent&link-type=html"},"head":"§301. Authorization of appropriations","tname":"The Public Health and Welfare","by":{"1":"29, 29","2":"35, 37, 43"}},{"t":"usc","label":"42 U.S.C. § 302","url":"https://www.law.cornell.edu/uscode/text/42/302","subs":["(a)(8)"],"by":{"1":"29"}},{"t":"usc","label":"42 U.S.C. § 601","url":"https://www.law.cornell.edu/uscode/text/42/601","by":{"1":"29"}},{"t":"usc","label":"42 U.S.C. § 1201","url":"https://www.law.cornell.edu/uscode/text/42/1201","by":{"1":"29"}},{"t":"usc","label":"42 U.S.C. § 1202","url":"https://www.law.cornell.edu/uscode/text/42/1202","subs":["(a)(11)"],"by":{"1":"29"}},{"t":"usc","label":"42 U.S.C. § 1301","url":"https://www.law.cornell.edu/uscode/text/42/1301","by":{"1":"24"}},{"t":"usc","label":"42 U.S.C. § 1315","url":"https://www.law.cornell.edu/uscode/text/42/1315","subs":["(a)(1)"],"by":{"1":"24"}},{"t":"usc","label":"42 U.S.C. § 1316","url":"https://www.law.cornell.edu/uscode/text/42/1316","subs":["(a)(1)","(b)","(a)"],"stext":{"head":"§1316. Administrative and judicial review of public assistance determinations","paras":[[0,"(a) Determination of conformity with requirements for approval; petition for reconsideration; hearing; time limitations; review by court of appeals"],[0,"(1) Whenever a State plan is submitted to the Secretary by a State for approval under subchapter I, X, XIV, XVI, or XIX, he shall, not later than 90 days after the date the plan is submitted to him, make a determination as to whether it conforms to the requirements for approval under such subchapter. The 90-day period provided herein may be extended by written agreement of the Secretary and the affected State."],[0,"(2) Any State dissatisfied with a determination of the Secretary under paragraph (1) of this subsection with respect to any plan may, within 60 days after it has been notified of such determination, file a petition with the Secretary for reconsideration of the issue of whether such plan conforms to the requirements for approval under such subchapter. Within 30 days after receipt of such a petition, the Secretary shall notify the State of the time and place at which a hearing will be held for the purpose of reconsidering such issue. Such hearing shall be held not less than 20 days nor more than 60 days after the date notice of such hearing is furnished to such State, unless the Secretary and such State agree in writing to holding the hearing at another time. The Secretary shall affirm, modify, or reverse his original determination within 60 days of the conclusion of the hearing."],[0,"(3) Any State which is dissatisfied with a final determination made by the Secretary on such a reconsideration or a final determination of the Secretary under section 304, 1204, 1354, 1384, or 1396c of this title may, within 60 days after it has been notified of such determination, file with the United States court of appeals for the circuit in which such State is located a petition for review of such determination. A copy of the petition shall be forthwith transmitted by the clerk of the court to the Secretary. The Secretary thereupon shall file in the court the record of the proceedings on which he based his determination as provided in section 2112 of title 28."],[0,"(4) The findings of fact by the Secretary, if supported by substantial evidence, shall be conclusive; but the court, for good cause shown, may remand the case to the Secretary to take further evidence, and the Secretary may thereupon make new or modified findings of fact and may modify his previous action, and shall certify to the court the transcript and record of the further proceedings. Such new or modified findings of fact shall likewise be conclusive if supported by substantial evidence."],[0,"(5) The court shall have jurisdiction to affirm the action of the Secretary or to set it aside, in whole or in part. The judgment of the court shall be subject to review by the Supreme Court of the United States upon certiorari or certification as provided in section 1254 of title 28."],[0,"(b) Amendment of plans"],[0,"For the purposes of subsection (a), any amendment of a State plan approved under subchapter I, X, XIV, XVI, or XIX, may, at the option of the State, be treated as the submission of a new State plan."],[0,"(c) Restitution when Secretary reverses his determination"],[0,"Action pursuant to an initial determination of the Secretary described in subsection (a) shall not be stayed pending reconsideration, but in the event that the Secretary subsequently determines that his initial determination was incorrect he shall certify restitution forthwith in a lump sum of any funds incorrectly withheld or otherwise denied."],[0,"(d) Disallowance of items covered under other subchapters"],[0,"Whenever the Secretary determines that any item or class of items on account of which Federal financial participation is claimed under subchapter I, X, XIV,1 XVI, shall be disallowed for such participation, the State shall be entitled to and upon request shall receive a reconsideration of the disallowance."],[0,"(e) Disallowance of items covered under subchapter XIX"],[0,"(1) Whenever the Secretary determines that any item or class of items on account of which Federal financial participation is claimed under subchapter XIX shall be disallowed for such participation, the State shall be entitled to and upon request shall receive a reconsideration of the disallowance, provided that such request is made during the 60-day period that begins on the date the State receives notice of the disallowance."],[0,"(2)(A) A State may appeal a disallowance of a claim for federal 2 financial participation under subchapter XIX by the Secretary, or an unfavorable reconsideration of a disallowance, during the 60-day period that begins on the date the State receives notice of the disallowance or of the unfavorable reconsideration, in whole or in part, to the Departmental Appeals Board, established in the Department of Health and Human Services (in this paragraph referred to as the \"Board\"), by filing a notice of appeal with the Board."],[0,"(B) The Board shall consider a State's appeal of a disallowance of such a claim (or of an unfavorable reconsideration of a disallowance) on the basis of such documentation as the State may submit and as the Board may require to support the final decision of the Board. In deciding whether to uphold a disallowance of such a claim or any portion thereof, the Board shall be bound by all applicable laws and regulations and shall conduct a thorough review of the issues, taking into account all relevant evidence. The Board's decision of an appeal under subparagraph (A) shall be the final decision of the Secretary and shall be subject to reconsideration by the Board only upon motion of either party filed during the 60-day period that begins on the date of the Board's decision or to judicial review in accordance with subparagraph (C)."],[0,"(C) A State may obtain judicial review of a decision of the Board by filing an action in any United States District Court located within the appealing State (or, if several States jointly appeal the disallowance of claims for Federal financial participation under section 1396b of this title, in any United States District Court that is located within any State that is a party to the appeal) or the United States District Court for the District of Columbia. Such an action may only be filed—"],[1,"(i) if no motion for reconsideration was filed within the 60-day period specified in subparagraph (B), during such 60-day period; or"],[1,"(ii) if such a motion was filed within such period, during the 60-day period that begins on the date of the Board's decision on such motion."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1316?type=usc&year=mostrecent&link-type=html"},"head":"§1316. Administrative and judicial review of public assistance determinations","tname":"The Public Health and Welfare","by":{"1":"5, 5","2":"44"}},{"t":"usc","label":"42 U.S.C. § 1396","url":"https://www.law.cornell.edu/uscode/text/42/1396","stext":{"head":"§1396. Medicaid and CHIP Payment and Access Commission","paras":[[0,"(a) Establishment"],[0,"There is hereby established the Medicaid and CHIP Payment and Access Commission (in this section referred to as \"MACPAC\")."],[0,"(b) Duties"],[0,"(1) Review of access policies for all States and annual reports"],[1,"MACPAC shall—"],[2,"(A) review policies of the Medicaid program established under this subchapter (in this section referred to as \"Medicaid\") and the State Children's Health Insurance Program established under subchapter XXI (in this section referred to as \"CHIP\") affecting access to covered items and services, including topics described in paragraph (2);"],[2,"(B) make recommendations to Congress, the Secretary, and States concerning such access policies;"],[2,"(C) by not later than March 15 of each year (beginning with 2010), submit a report to Congress containing the results of such reviews and MACPAC's recommendations concerning such policies; and"],[2,"(D) by not later than June 15 of each year (beginning with 2010), submit a report to Congress containing an examination of issues affecting Medicaid and CHIP, including the implications of changes in health care delivery in the United States and in the market for health care services on such programs."],[0,"(2) Specific topics to be reviewed"],[1,"Specifically, MACPAC shall review and assess the following:"],[0,"(A) Medicaid and CHIP payment policies"],[2,"Payment policies under Medicaid and CHIP, including—"],[3,"(i) the factors affecting expenditures for the efficient provision of items and services in different sectors, including the process for updating payments to medical, dental, and health professionals, hospitals, residential and long-term care providers, providers of home and community based services, Federally-qualified health centers and rural health clinics, managed care entities, and providers of other covered items and services;"],[3,"(ii) payment methodologies; and"],[3,"(iii) the relationship of such factors and methodologies to access and quality of care for Medicaid and CHIP beneficiaries (including how such factors and methodologies enable such beneficiaries to obtain the services for which they are eligible, affect provider supply, and affect providers that serve a disproportionate share of low-income and other vulnerable populations)."],[0,"(B) Eligibility policies"],[2,"Medicaid and CHIP eligibility policies, including a determination of the degree to which Federal and State policies provide health care coverage to needy populations."],[0,"(C) Enrollment and retention processes"],[2,"Medicaid and CHIP enrollment and retention processes, including a determination of the degree to which Federal and State policies encourage the enrollment of individuals who are eligible for such programs and screen out individuals who are ineligible, while minimizing the share of program expenses devoted to such processes."],[0,"(D) Coverage policies"],[2,"Medicaid and CHIP benefit and coverage policies, including a determination of the degree to which Federal and State policies provide access to the services enrollees require to improve and maintain their health and functional status."],[0,"(E) Quality of care"],[2,"Medicaid and CHIP policies as they relate to the quality of care provided under those programs, including a determination of the degree to which Federal and State policies achieve their stated goals and interact with similar goals established by other purchasers of health care services."],[0,"(F) Interaction of Medicaid and CHIP payment policies with health care delivery generally"],[2,"The effect of Medicaid and CHIP payment policies on access to items and services for children and other Medicaid and CHIP populations other than under this subchapter or subchapter XXI and the implications of changes in health care delivery in the United States and in the general market for health care items and services on Medicaid and CHIP."],[0,"(G) Interactions with Medicare and Medicaid"],[2,"Consistent with paragraph (11), the interaction of policies under Medicaid and the Medicare program under subchapter XVIII, including with respect to how such interactions affect access to services, payments, and dual eligible individuals."],[0,"(H) Other access policies"],[2,"The effect of other Medicaid and CHIP policies on access to covered items and services, including policies relating to transportation and language barriers and preventive, acute, and long-term services and supports."],[0,"(3) Recommendations and reports of State-specific data"],[1,"MACPAC shall—"],[2,"(A) review national and State-specific Medicaid and CHIP data; and"],[2,"(B) submit reports and recommendations to Congress, the Secretary, and States based on such reviews."],[0,"(4) Creation of early-warning system"],[1,"MACPAC shall create an early-warning system to identify provider shortage areas, as well as other factors that adversely affect, or have the potential to adversely affect, access to care by, or the health care status of, Medicaid and CHIP beneficiaries. MACPAC shall include in the annual report required under paragraph (1)(D) a description of all such areas or problems identified with respect to the period addressed in the report."],[0,"(5) Comments on certain secretarial reports and regulations"],[0,"(A) Certain secretarial reports"],[2,"If the Secretary submits to Congress (or a committee of Congress) a report that is required by law and that relates to access policies, including with respect to payment policies, under Medicaid or CHIP, the Secretary shall transmit a copy of the report to MACPAC. MACPAC shall review the report and, not later than 6 months after the date of submittal of the Secretary's report to Congress, shall submit to the appropriate committees of Congress and the Secretary written comments on such report. Such comments may include such recommendations as MACPAC deems appropriate."],[0,"(B) Regulations"],[2,"MACPAC shall review Medicaid and CHIP regulations and may comment through submission of a report to the appropriate committees of Congress and the Secretary, on any such regulations that affect access, quality, or efficiency of health care."],[0,"(6) Agenda and additional reviews"],[0,"(A) In general"],[2,"MACPAC shall consult periodically with the chairmen and ranking minority members of the appropriate committees of Congress regarding MACPAC's agenda and progress towards achieving the agenda. MACPAC may conduct additional reviews, and submit additional reports to the appropriate committees of Congress, from time to time on such topics relating to the program under this subchapter or subchapter XXI as may be requested by such chairmen and members and as MACPAC deems appropriate."],[0,"(B) Review and reports regarding Medicaid DSH"],[0,"(i) In general"],[3,"MACPAC shall review and submit an annual report to Congress on disproportionate share hospital payments under section 1396r–4 of this title. Each report shall include the information specified in clause (ii)."],[0,"(ii) Required report information"],[3,"Each report required under this subparagraph shall include the following:"],[4,"(I) Data relating to changes in the number of uninsured individuals."],[4,"(II) Data relating to the amount and sources of hospitals' uncompensated care costs, including the amount of such costs that are the result of providing unreimbursed or under-reimbursed services, charity care, or bad debt."],[4,"(III) Data identifying hospitals with high levels of uncompensated care that also provide access to essential community services for low-income, uninsured, and vulnerable populations, such as graduate medical education, and the continuum of primary through quarternary care, including the provision of trauma care and public health services."],[4,"(IV) State-specific analyses regarding the relationship between the most recent State DSH allotment and the projected State DSH allotment for the succeeding year and the data reported under subclauses (I), (II), and (III) for the State."],[0,"(iii) Data"],[3,"Notwithstanding any other provision of law, the Secretary regularly shall provide MACPAC with the most recent State reports and most recent independent certified audits submitted under section 1396r–4(j) of this title, cost reports submitted under subchapter XVIII, and such other data as MACPAC may request for purposes of conducting the reviews and preparing and submitting the annual reports required under this subparagraph."],[0,"(iv) Submission deadlines"],[3,"The first report required under this subparagraph shall be submitted to Congress not later than February 1, 2016. Subsequent reports shall be submitted as part of, or with, each annual report required under paragraph (1)(C) during the period of fiscal years 2017 through 2024."],[0,"(7) Availability of reports"],[1,"MACPAC shall transmit to the Secretary a copy of each report submitted under this subsection and shall make such reports available to the public."],[0,"(8) Appropriate committee of Congress"],[1,"For purposes of this section, the term \"appropriate committees of Congress\" means the Committee on Energy and Commerce of the House of Representatives and the Committee on Finance of the Senate."],[0,"(9) Voting and reporting requirements"],[1,"With respect to each recommendation contained in a report submitted under paragraph (1), each member of MACPAC shall vote on the recommendation, and MACPAC shall include, by member, the results of that vote in the report containing the recommendation."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1396?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1396. Medicaid and CHIP Payment and Access Commission","tname":"The Public Health and Welfare","by":{"1":"5"}},{"t":"law","label":"Pub. L. No. 90-248","url":"https://www.govinfo.gov/link/statute/81/821","by":{"1":"23","2":"19, 30","3":"14"}},{"t":"reg","label":"43 Fed. Reg. 45,176","url":"https://www.govinfo.gov/link/fr/43/45176","by":{"1":"6"}},{"t":"case","label":"Department of Agric. Rural Develop. Rural Hous. Serv. v. Kirtz","cite":"601 U.S. 42","y":2024,"id":"2023/22-846","sc":1,"sum":"A consumer may sue a federal agency under 15 U. S. C. §§1681n and 1681o for defying the terms of the Fair Credit Reporting Act.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"26","3":"8, 12–14"}},{"t":"case","label":"Encino Motorcars, LLC v. Navarro","cite":"579 U.S. 211","y":2016,"id":"2015/15-415","sc":1,"sum":"The Court held that, because the Department of Labor did not give adequate reasons for altering its position on whether service advisors are exempt from overtime compensation under the Fair Labor Standards Act (FLSA), the case should be remanded for reinterpretation that does not give controlling weight to the Department’s 2011 position.","sumSrc":"Oyez","by":{"2":"25"}},{"t":"case","label":"Fitzgerald v. Barnstable Sch. Comm.","cite":"555 U.S. 246","y":2009,"id":"2008/07-1125","sc":1,"sum":"The Court found that a claim filed under Title IX for violation of the Equal Protection Clause of the fourteenth Amendment does not preclude the use of 42 U.S.C. Section 1983 which protects against the deprivation of any rights guaranteed by the Constitution and federal law.","sumSrc":"Oyez","by":{"2":"42"}},{"t":"case","label":"Harris v. Olszewski","cite":"442 F.3d 456","y":2006,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/442/456/","op":1,"by":{"2":"24, 39"}},{"t":"case","label":"Henderson ex rel. Henderson v. Shinseki","cite":"562 U.S. 428","y":2011,"id":"2010/09-1036","sc":1,"op":1,"sum":"The Court held that missing the deadline for filing a notice of appeal with the Veterans Court did not bar a plaintiff from making a claim.","sumSrc":"Oyez","by":{"2":"25","3":"8"}},{"t":"case","label":"Kerr v. Planned Parenthood","cite":"2024 WL 518085","y":2024,"court":"U.S. Dec. 18","by":{"2":"47"}},{"t":"case","label":"Kerr v. Planned Parenthood S. Atl.","cite":"143 S. Ct. 2633","y":2023,"url":"https://www.courtlistener.com/c/S.%20Ct./143/2633/","sc":1,"by":{"2":"11"}},{"t":"case","label":"Kingdomware Techs., Inc. v. United States","cite":"579 U.S. 162","y":2016,"id":"2015/14-916","sc":1,"sum":"The Court determined that the Court had jurisdiction to address the merits of the case even if the contracts had already been performed, and the Department of Veterans Affairs’ “set-aside” for veteran-owned businesses is mandatory.","sumSrc":"Oyez","by":{"2":"27"}},{"t":"case","label":"Middlesex Cnty. Sewerage Auth. v. National Sea Clammers Ass’n","cite":"453 U.S. 1","y":1981,"id":"1980/79-1711","sc":1,"sum":"Respondents (an organization whose members harvest fish and shellfish off the coast of New York and New Jersey and one individual member) brought suit in Federal District Court against petitioners (various governmental entities and officials from New York, New Jersey, and the Federal Government), alleging damage to fishing grounds caused by discharges and ocean dumping of sewage and other waste. Invoking a number of …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"42, 43"}},{"t":"case","label":"MOAC Mall Holdings LLC v. Transform Holdco LLC","cite":"598 U.S. 288","y":2023,"id":"2022/21-1270","sc":1,"sum":"Section 363(m) of the Bankruptcy Code—which restricts the effects of certain successful appeals of judicially authorized sales or leases of bankruptcy-estate property—is not a jurisdictional provision.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"25"}},{"t":"case","label":"National Inst. of Fam. & Life Advs. v. Becerra","cite":"585 U.S. 755","y":2018,"id":"2017/16-1140","sc":1,"sum":"The Court decided that pro-life pregnancy center petitioners were likely to succeed on their claim that the California Reproductive Freedom, Accountability, Comprehensive Care, and Transparency Act violated the First Amendment.","sumSrc":"Oyez","by":{"2":"21"}},{"t":"case","label":"Ohio v. EPA","cite":"603 U.S. 279","y":2024,"url":"https://supreme.justia.com/cases/federal/us/603/279/","sc":1,"op":2,"by":{"2":"40"}},{"t":"case","label":"Patsy v. Board of Regents of State of Fla.","cite":"457 U.S. 496","y":1982,"id":"1981/80-1874","sc":1,"sum":"Exhaustion of state administrative remedies is not a prerequisite to an action under § 1983.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"45"}},{"t":"case","label":"Planned Parenthood of Ind., Inc. v. Commissioner of Ind. State Dep’t of Health","cite":"699 F.3d 962","y":2012,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/699/962/","op":1,"by":{"2":"24"}},{"t":"case","label":"Planned Parenthood of Kan. & Mid-Mo. v. Andersen","cite":"882 F.3d 1205","y":2018,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/882/1205/","by":{"2":"24"}},{"t":"case","label":"Polk v. Yee","cite":"36 F.4th 939","y":2022,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/36/939/","op":1,"by":{"2":"38, 39","3":"20"}},{"t":"case","label":"Smith v. Robinson","cite":"468 U.S. 992","y":1984,"id":"1983/82-2120","sc":1,"sum":"When the Superintendent of Schools in Cumberland, R. I., informed petitioner parents of petitioner child, who suffers from cerebral palsy and other handicaps, that the School Committee no longer would fund the child's placement in a special educational program, the parents, in addition to appealing the Superintendent's decision to the School Committee and thereafter through the state administrative process, filed an …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"42, 43"}},{"t":"const","label":"Amendment VIII","clauses":[["eighth-amendment","Eighth Amendment"]],"text":"Excessive bail shall not be required, nor excessive fines imposed, nor cruel and unusual punishments inflicted.","by":{"2":"28"}},{"t":"const","label":"Amendment XIV","clauses":[["citizenship-clause","Citizenship Clause"],["privileges-or-immunities","Privileges or Immunities Clause"],["due-process-14","Due Process Clause (Fourteenth Amendment)"],["equal-protection","Equal Protection Clause"],["disqualification","Disqualification Clause (Section 3)"],["enforcement-14","Enforcement Clause (Section 5)"]],"by":{"2":"9"}},{"t":"usc","label":"40 U.S.C. § 276a","url":"https://www.law.cornell.edu/uscode/text/40/276a","subs":["(a)(1980)"],"by":{"2":"24"}},{"t":"usc","label":"42 U.S.C. § 304","url":"https://www.law.cornell.edu/uscode/text/42/304","subs":["(2)"],"by":{"2":"37"}},{"t":"usc","label":"42 U.S.C. § 609","url":"https://www.law.cornell.edu/uscode/text/42/609","subs":["(a)(8)"],"by":{"2":"37"}},{"t":"usc","label":"42 U.S.C. § 1320a-7","url":"https://www.law.cornell.edu/uscode/text/42/1320a-7","by":{"2":"48"}},{"t":"usc","label":"42 U.S.C. § 1395a","url":"https://www.law.cornell.edu/uscode/text/42/1395a","subs":["(a)"],"stext":{"head":"§1395a. Free choice by patient guaranteed","paras":[[0,"(a) Basic freedom of choice"],[0,"Any individual entitled to insurance benefits under this subchapter may obtain health services from any institution, agency, or person qualified to participate under this subchapter if such institution, agency, or person undertakes to provide him such services."],[0,"(b) Use of private contracts by medicare beneficiaries"],[0,"(1) In general"],[1,"Subject to the provisions of this subsection, nothing in this subchapter shall prohibit a physician or practitioner from entering into a private contract with a medicare beneficiary for any item or service—"],[2,"(A) for which no claim for payment is to be submitted under this subchapter, and"],[2,"(B) for which the physician or practitioner receives—"],[3,"(i) no reimbursement under this subchapter directly or on a capitated basis, and"],[3,"(ii) receives no amount for such item or service from an organization which receives reimbursement for such item or service under this subchapter directly or on a capitated basis."],[0,"(2) Beneficiary protections"],[0,"(A) In general"],[2,"Paragraph (1) shall not apply to any contract unless—"],[3,"(i) the contract is in writing and is signed by the medicare beneficiary before any item or service is provided pursuant to the contract;"],[3,"(ii) the contract contains the items described in subparagraph (B); and"],[3,"(iii) the contract is not entered into at a time when the medicare beneficiary is facing an emergency or urgent health care situation."],[0,"(B) Items required to be included in contract"],[2,"Any contract to provide items and services to which paragraph (1) applies shall clearly indicate to the medicare beneficiary that by signing such contract the beneficiary—"],[3,"(i) agrees not to submit a claim (or to request that the physician or practitioner submit a claim) under this subchapter for such items or services even if such items or services are otherwise covered by this subchapter;"],[3,"(ii) agrees to be responsible, whether through insurance or otherwise, for payment of such items or services and understands that no reimbursement will be provided under this subchapter for such items or services;"],[3,"(iii) acknowledges that no limits under this subchapter (including the limits under section 1395w–4(g) of this title) apply to amounts that may be charged for such items or services;"],[3,"(iv) acknowledges that Medigap plans under section 1395ss of this title do not, and other supplemental insurance plans may elect not to, make payments for such items and services because payment is not made under this subchapter; and"],[3,"(v) acknowledges that the medicare beneficiary has the right to have such items or services provided by other physicians or practitioners for whom payment would be made under this subchapter."],[2,"Such contract shall also clearly indicate whether the physician or practitioner is excluded from participation under the medicare program under section 1320a–7 of this title."],[0,"(3) Physician or practitioner requirements"],[0,"(A) In general"],[2,"Paragraph (1) shall not apply to any contract entered into by a physician or practitioner unless an affidavit described in subparagraph (B) is in effect during the period any item or service is to be provided pursuant to the contract."],[0,"(B) Affidavit"],[2,"An affidavit is described in this subparagraph if—"],[3,"(i) the affidavit identifies the physician or practitioner and is in writing and is signed by the physician or practitioner;"],[3,"(ii) the affidavit provides that the physician or practitioner will not submit any claim under this subchapter for any item or service provided to any medicare beneficiary (and will not receive any reimbursement or amount described in paragraph (1)(B) for any such item or service) during the applicable 2-year period (as defined in subparagraph (D)); and"],[3,"(iii) a copy of the affidavit is filed with the Secretary no later than 10 days after the first contract to which such affidavit applies is entered into."],[0,"(C) Enforcement"],[2,"If a physician or practitioner signing an affidavit under subparagraph (B) knowingly and willfully submits a claim under this subchapter for any item or service provided during the applicable 2-year period (or receives any reimbursement or amount described in paragraph (1)(B) for any such item or service) with respect to such affidavit—"],[3,"(i) this subsection shall not apply with respect to any items and services provided by the physician or practitioner pursuant to any contract on and after the date of such submission and before the end of such period; and"],[3,"(ii) no payment shall be made under this subchapter for any item or service furnished by the physician or practitioner during the period described in clause (i) (and no reimbursement or payment of any amount described in paragraph (1)(B) shall be made for any such item or service)."],[0,"(D) Applicable 2-year periods for effectiveness of affidavits"],[2,"In this subsection, the term \"applicable 2-year period\" means, with respect to an affidavit of a physician or practitioner under subparagraph (B), the 2-year period beginning on the date the affidavit is signed and includes each subsequent 2-year period unless the physician or practitioner involved provides notice to the Secretary (in a form and manner specified by the Secretary), not later than 30 days before the end of the previous 2-year period, that the physician or practitioner does not want to extend the application of the affidavit for such subsequent 2-year period."],[0,"(4) Limitation on actual charge and claim submission requirement not applicable"],[1,"Section 1395w–4(g) of this title shall not apply with respect to any item or service provided to a medicare beneficiary under a contract described in paragraph (1)."],[0,"(5) Posting of information on opt-out physicians and practitioners"],[0,"(A) In general"],[2,"Beginning not later than February 1, 2016, the Secretary shall make publicly available through an appropriate publicly accessible website of the Department of Health and Human Services information on the number and characteristics of opt-out physicians and practitioners and shall update such information on such website not less often than annually."],[0,"(B) Information to be included"],[2,"The information to be made available under subparagraph (A) shall include at least the following with respect to opt-out physicians and practitioners:"],[3,"(i) Their number."],[3,"(ii) Their physician or professional specialty or other designation."],[3,"(iii) Their geographic distribution."],[3,"(iv) The timing of their becoming opt-out physicians and practitioners, relative, to the extent feasible, to when they first enrolled in the program under this subchapter and with respect to applicable 2-year periods."],[3,"(v) The proportion of such physicians and practitioners who billed for emergency or urgent care services."],[0,"(6) Definitions"],[1,"In this subsection:"],[0,"(A) Medicare beneficiary"],[2,"The term \"medicare beneficiary\" means an individual who is entitled to benefits under part A or enrolled under part B."],[0,"(B) Physician"],[2,"The term \"physician\" has the meaning given such term by paragraphs (1), (2), (3), and (4) of section 1395x(r) of this title."],[0,"(C) Practitioner"],[2,"The term \"practitioner\" has the meaning given such term by section 1395u(b)(18)(C) of this title."],[0,"(D) Opt-out physician or practitioner"],[2,"The term \"opt-out physician or practitioner\" means a physician or practitioner who has in effect an affidavit under paragraph (3)(B)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1395a?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1395a. Free choice by patient guaranteed","tname":"The Public Health and Welfare","by":{"2":"34, 34","3":"14, 16"}},{"t":"usc","label":"42 U.S.C. § 1396d","url":"https://www.law.cornell.edu/uscode/text/42/1396d","subs":["(a)","(a)(4)(C)"],"by":{"2":"3, 19"}},{"t":"usc","label":"42 U.S.C. § 1396n","url":"https://www.law.cornell.edu/uscode/text/42/1396n","subs":["(b)","(b)(1)"],"by":{"2":"5, 19, 21, 27, 33, 32"}},{"t":"usc","label":"42 U.S.C. § 1397ff","url":"https://www.law.cornell.edu/uscode/text/42/1397ff","subs":["(c)(1)"],"by":{"2":"37"}},{"t":"usc","label":"42 U.S.C. § 1437a","url":"https://www.law.cornell.edu/uscode/text/42/1437a","subs":["(a)(1982)"],"by":{"2":"26, 28"}},{"t":"law","label":"Pub. L. No. 99-272","url":"https://www.govinfo.gov/link/statute/100/210","by":{"2":"33"}},{"t":"law","label":"Pub. L. No. 100-203","url":"https://www.govinfo.gov/link/statute/101/1330","by":{"2":"33"}},{"t":"law","label":"Pub. L. No. 97-35","url":"https://www.govinfo.gov/link/statute/95/809","by":{"2":"32"}},{"t":"law","label":"Pub. L. No. 89-97","url":"https://www.govinfo.gov/link/statute/79/291","by":{"2":"30"}},{"t":"reg","label":"42 C.F.R. § 447.203","url":"https://www.ecfr.gov/current/title-42/section-447.203","by":{"2":"49"}},{"t":"case","label":"Arlington Central School District Board of Education v. Murphy","cite":"548 U.S. 291","y":2006,"id":"2005/05-18","sc":1,"op":1,"sum":"In a 6-to-3 decision authored by Justice Samuel Alito, the Supreme Court held that IDEA did not authorize reimbursement of expert fees. \"While authorizing the award of reasonable attorney's fees, the Act contains detailed provisions that are designed to ensure that such awards are indeed reasonable,\" Justice Alito wrote. \"The absence of any comparable provisions relating to expert fees strongly suggests that recovery of expert fees is not authorized.\" Justice Alito went on to write that the case was made even simpler by the fact that, as an exercise of Congress's Spending Clause power, any provision requiring reimbursement of expert fees would have had to be \"unambiguous,\" which it clearly was not.","sumSrc":"Oyez","by":{"3":"13"}},{"t":"case","label":"Bryson v. Shumway","cite":"308 F.3d 79","y":2002,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/308/79/","sum":"Finding private right in 42 U.S.C. 1396a(a)(8).","sumSrc":"brief:3","by":{"3":"20"}},{"t":"case","label":"California Association of Rural Health Clinics v. Douglas","cite":"738 F.3d 1007","y":2013,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/738/1007/","by":{"3":"20"}},{"t":"case","label":"City of Chicago v. Environmental Defense Fund","cite":"511 U.S. 328","y":1994,"id":"1993/92-1639","sc":1,"sum":"Section 3001(i) does not exempt the MWC ash generated by petitioners' facility from Subtitle C regulation as hazardoug waste. Although a pre-§ 3001(i) EPA regulation provided a \"waste stream\" exemption covering household waste from generation through treatment to final disposal of residues, petitioners' facility would not have come within that exemption because it burned something in addition to household waste; the …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"14"}},{"t":"case","label":"Gonzalez v. Thaler","cite":"565 U.S. 134","y":2012,"id":"2011/10-895","sc":1,"sum":"The Court held that a prisoner who does not seek review in a state’s highest court faces final judgment for the purposes of Section 2244(d)(1)(A) upon “expiration of the time for seeking such review.”","sumSrc":"Oyez","by":{"3":"12"}},{"t":"case","label":"Gross v. FBL Financial Services, Inc.","cite":"557 U.S. 167","y":2009,"id":"2008/08-441","sc":1,"sum":"The Court held that a plaintiff must show that age was the \"but-for\" cause for the defendant's action in an Age Discrimination in Employment Act claim.","sumSrc":"Oyez","by":{"3":"17"}},{"t":"case","label":"Pediatric Specialty Care, Inc. v. Arkansas Department of Human Services","cite":"443 F.3d 1005","y":2006,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/443/1005/","by":{"3":"20"}},{"t":"case","label":"Sabree v. Richman","cite":"367 F.3d 180","y":2004,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/367/180/","by":{"3":"20"}},{"t":"case","label":"Sanchez v. Johnson","cite":"416 F.3d 1051","y":2005,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/416/1051/","by":{"3":"16"}},{"t":"case","label":"Sossamon v. Texas","cite":"563 U.S. 277","y":2011,"id":"2010/08-1438","sc":1,"sum":"The Court held that a person may not sue a state official in his individual capacity for damages under the Religious Land Use and Institutional Persons Act.","sumSrc":"Oyez","by":{"3":"12"}},{"t":"case","label":"United States v. National Bank of Commerce","cite":"472 U.S. 713","y":1985,"id":"1984/84-498","sc":1,"sum":"The IRS had a right to levy on the joint accounts in question.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"4"}},{"t":"reg","label":"42 C.F.R. § 1002.3","url":"https://www.ecfr.gov/current/title-42/section-1002.3","by":{"3":"24"}}]};